          touchdownRing.scale.setScalar(kind === 'crash' ? 0.9 : kind === 'takeoff' ? 0.72 : 0.58);
          touchdownRing.material.color.setHex(kind === 'crash' ? 0xfb923c : kind === 'takeoff' ? 0x67e8f9 : 0xfde68a);
