            thermalSpiralPositions[thermalSpiralIndex * 3] = Math.cos(thermalSpiralAngle) * thermalSpiralRadius;
            thermalSpiralPositions[thermalSpiralIndex * 3 + 1] = 42 + thermalSpiralProgress * 485;
